create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','agent');
create type public.conversation_mode as enum ('AI','HUMAN');
create type public.lead_stage as enum ('new','qualifying','quote_draft','quote_sent','negotiation','booked','lost');
create type public.quote_status as enum ('draft','pending_review','approved','sent','viewed','accepted','expired','rejected');
create type public.job_status as enum ('queued','running','done','failed','dead');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,brand jsonb not null default '{}',settings jsonb not null default '{"timezone":"Asia/Kolkata","currency":"INR","quiet_hours":{"start":"21:00","end":"09:00"}}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.members(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,user_id uuid not null references auth.users on delete cascade,role member_role not null default 'agent',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,user_id));
create table public.whatsapp_accounts(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,waba_id text,phone_number_id text,display_phone text,access_token_encrypted text,app_secret_encrypted text,verify_token text,status text not null default 'disconnected',mode text not null default 'sandbox' check(mode in('live','sandbox')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.contacts(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,name text,wa_id text not null,language_pref text,opted_in boolean not null default false,opted_in_at timestamptz,opted_out boolean not null default false,opted_out_at timestamptz,source text,tags text[] not null default '{}',notes text,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,wa_id));
create table public.conversations(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,contact_id uuid not null references contacts on delete cascade,mode conversation_mode not null default 'AI',assigned_to uuid references auth.users,status text not null default 'open',last_inbound_at timestamptz,last_outbound_at timestamptz,window_expires_at timestamptz,unread_count int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.messages(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,conversation_id uuid not null references conversations on delete cascade,direction text not null check(direction in('inbound','outbound')),wamid text,type text not null default 'text',body text,media_path text,status text not null default 'queued',error text,sender text not null,ai_trace_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,wamid));
create table public.leads(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,contact_id uuid not null references contacts,conversation_id uuid not null references conversations,stage lead_stage not null default 'new',requirement jsonb not null default '{}',owner_id uuid references auth.users,lost_reason text,value_estimate bigint,booked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.packages(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,name text not null,destination text not null,nights int not null,theme text,highlights text,inclusions text[] not null default '{}',exclusions text[] not null default '{}',terms text,cancellation_policy text,hero_image_path text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.package_days(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,package_id uuid not null references packages on delete cascade,day_no int not null,title text not null,description text,meals text,hotel_stay_city text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.rate_cards(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,package_id uuid not null references packages on delete cascade,hotel_category text not null,season text not null,date_ranges daterange[],price_per_adult_double bigint not null,price_per_child_with_bed bigint not null default 0,price_per_child_no_bed bigint not null default 0,single_supplement bigint not null default 0,infant_price bigint not null default 0,min_pax int not null default 1,valid_from date not null,valid_to date not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.pricing_rules(id uuid primary key default gen_random_uuid(),org_id uuid not null unique references organizations on delete cascade,markup_percent numeric not null default 15,tax_config jsonb not null default '{"gst_percent":5,"tcs_percent":0,"applies_to":"domestic"}',rounding int not null default 100,discount_limits jsonb not null default '{"max_percent_without_owner_approval":5}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.quotes(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,lead_id uuid not null references leads,version int not null default 1,status quote_status not null default 'draft',package_id uuid references packages,line_items jsonb not null default '[]',subtotal bigint not null default 0,taxes bigint not null default 0,total bigint not null default 0,token_amount bigint not null default 0,valid_until timestamptz,share_token text unique not null default encode(gen_random_bytes(24),'hex'),pdf_path text,created_by text not null default 'ai',approved_by uuid references auth.users,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(lead_id,version));
create table public.followup_sequences(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,name text not null,trigger text not null,active boolean not null default true,stop_conditions jsonb not null default '["reply","accepted","opt_out","human"]',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.followup_steps(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,sequence_id uuid not null references followup_sequences on delete cascade,step_no int not null,delay_minutes int not null,channel text not null,content text not null,template_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.jobs(id uuid primary key default gen_random_uuid(),org_id uuid references organizations on delete cascade,type text not null,payload jsonb not null default '{}',run_at timestamptz not null default now(),attempts int not null default 0,max_attempts int not null default 5,status job_status not null default 'queued',locked_at timestamptz,last_error text,dedupe_key text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,dedupe_key));
create table public.wa_templates(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,name text not null,language text not null default 'en',category text,status text not null default 'draft',body text not null,variables jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.payments(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,quote_id uuid not null references quotes,razorpay_link_id text,amount bigint not null,status text not null default 'created',paid_at timestamptz,raw jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(razorpay_link_id));
create table public.knowledge_items(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,question text not null,answer text not null,tags text[] not null default '{}',search_vector tsvector generated always as(to_tsvector('english',question||' '||answer)) stored,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.ai_traces(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,conversation_id uuid references conversations,model text not null,input_tokens int not null default 0,output_tokens int not null default 0,cost_inr numeric not null default 0,tool_calls jsonb not null default '[]',latency_ms int,outcome text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_log(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations on delete cascade,actor uuid,action text not null,entity text not null,entity_id uuid,diff jsonb not null default '{}',created_at timestamptz not null default now());
create table public.webhook_events(id uuid primary key default gen_random_uuid(),org_id uuid references organizations on delete cascade,provider text not null,event_key text,raw jsonb not null,processed_at timestamptz,error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider,event_key));
create unique index package_org_name_unique on packages(org_id,name);create unique index package_days_package_day_unique on package_days(package_id,day_no);create unique index rate_cards_unique on rate_cards(package_id,hotel_category,season,valid_from,valid_to);create unique index knowledge_org_question_unique on knowledge_items(org_id,question);create unique index wa_template_org_name_lang_unique on wa_templates(org_id,name,language);create unique index whatsapp_account_org_phone_unique on whatsapp_accounts(org_id,phone_number_id);
create index jobs_ready_idx on jobs(status,run_at) where status='queued';create index messages_conversation_idx on messages(org_id,conversation_id,created_at desc);create index knowledge_search_idx on knowledge_items using gin(search_vector);
create or replace function public.is_org_member(target_org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from members where org_id=target_org and user_id=auth.uid()) $$;
do $$ declare t text; begin foreach t in array array['organizations','members','whatsapp_accounts','contacts','conversations','messages','leads','packages','package_days','rate_cards','pricing_rules','quotes','followup_sequences','followup_steps','jobs','wa_templates','payments','knowledge_items','ai_traces','audit_log','webhook_events'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy tenant_access on public.%I for all using (public.is_org_member(org_id)) with check (public.is_org_member(org_id))',t); end loop; end $$;
create policy member_self_read on public.members for select using (user_id=auth.uid() or public.is_org_member(org_id));
create or replace function public.claim_jobs(batch_size int default 20) returns setof jobs language sql security definer set search_path=public as $$ with picked as(select id from jobs where status='queued' and run_at<=now() order by run_at for update skip locked limit batch_size) update jobs j set status='running',locked_at=now(),attempts=attempts+1,updated_at=now() from picked where j.id=picked.id returning j.* $$;
create or replace function public.simulator_inbound(p_org_id uuid,p_wa_id text,p_text text,opt_out boolean default false) returns jsonb language plpgsql security definer set search_path=public as $$ declare c contacts; cv conversations; m messages; begin if not exists(select 1 from whatsapp_accounts where org_id=p_org_id and mode='sandbox') then raise exception 'sandbox_not_enabled'; end if; insert into contacts(org_id,wa_id,opted_in,opted_in_at,opted_out,opted_out_at,source) values(p_org_id,p_wa_id,true,now(),opt_out,case when opt_out then now() end,'sandbox') on conflict(org_id,wa_id) do update set opted_in=true,opted_in_at=coalesce(contacts.opted_in_at,now()),opted_out=contacts.opted_out or opt_out,opted_out_at=case when opt_out then now() else contacts.opted_out_at end returning * into c; insert into conversations(org_id,contact_id,last_inbound_at,window_expires_at) values(p_org_id,c.id,now(),now()+interval '24 hours') returning * into cv; insert into messages(org_id,conversation_id,direction,type,body,sender,status) values(p_org_id,cv.id,'inbound','text',p_text,'customer','delivered') returning * into m; if opt_out then update jobs set status='dead',last_error='contact opted out' where org_id=p_org_id and payload->>'contact_id'=c.id::text and status='queued'; else insert into jobs(org_id,type,payload,dedupe_key) values(p_org_id,'agent.reply',jsonb_build_object('conversation_id',cv.id,'contact_id',c.id),'sim:'||m.id) on conflict do nothing; end if; return jsonb_build_object('conversation_id',cv.id,'message_id',m.id,'opted_out',opt_out); end $$;
create or replace function public.public_quote(token text) returns jsonb language sql security definer set search_path=public as $$ select jsonb_build_object('quote',to_jsonb(q),'package',to_jsonb(p),'lead',jsonb_build_object('requirement',l.requirement)) from quotes q join leads l on l.id=q.lead_id left join packages p on p.id=q.package_id where q.share_token=token and q.valid_until>now() and q.status in('approved','sent','viewed','accepted') $$;
